def test_hyb_mgga_xc_pw6b95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_pw6b95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.196851596337112e+00, -3.137877406246586e+00, -3.055289598301568e+00, -2.940986597762803e+00, -2.785442182991751e+00, -2.578841750124977e+00, -2.313726691416672e+00, -1.989609898812078e+00, -1.618586440617096e+00, -1.226101681949348e+00, -8.366361976345170e-01, -5.731157254146025e-01, -4.753943160495941e-01, -3.922800992414507e-01, -2.888773940751174e-01, -1.871850721312385e-01, -1.046067323724725e-01, -2.741069792782967e-02, -4.312468705752466e-04, -7.358448912519512e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


